package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import com.lianxibu.site.repository.jobs.JdbcFrozenInputs;
import java.util.*;
import org.junit.jupiter.api.*;

/** Native original source component facts only; heat count, whole-day closure and final candidate admission are separate. */
class NewsSourceReportEntityLeavesTest {
    NewsSourceReportComponentTest h;
    GenerationJdbcStoreTest fixture(){return new GenerationJdbcStoreTest();}
    @BeforeEach void setup()throws Exception{h=new NewsSourceReportComponentTest(){@Override GenerationJdbcStoreTest fixture(){return NewsSourceReportEntityLeavesTest.this.fixture();}};h.setup();}
    @Test void EveryOriginalAppliedMemberKeepsItsFullBodyEntityAndNativeImmutableReference(){var captured=h.capture();var leaves=captured.entityLeaves();assertEquals(h.h.done.stage().members().size(),leaves.size());assertTrue(leaves.size()>h.h.done.finalResult().result().selected().size());var seen=new HashSet<String>();for(var leaf:leaves){assertTrue(seen.add(leaf.itemId()));var fragment=h.h.done.stage().fragments().stream().filter(f->f.rootId().equals(leaf.rootId())).findFirst().orElseThrow();var chunk=h.h.done.plan().chunks().stream().filter(c->c.rootId().equals(fragment.rootId())).findFirst().orElseThrow();var fact=h.h.done.stage().members().stream().filter(f->f.itemId().equals(leaf.itemId())).findFirst().orElseThrow();var member=CanonicalJson.parse(chunk.snapshotJson()).get("members").valueStream().filter(m->m.get("id").asText().equals(leaf.itemId())).findFirst().orElseThrow();assertEquals(JdbcFrozenInputs.canonical(member.get("body")),leaf.bodyJson());assertEquals(chunk.inputHash(),leaf.inputHash());assertEquals(CanonicalJson.hash(CanonicalJson.Domain.CONTENT,CanonicalJson.parse(leaf.bodyJson())),leaf.bodyHash());assertEquals(fact.entityId(),leaf.entityId());assertEquals(fact.sourceItemId(),leaf.sourceItemId());assertEquals(fact.runId(),leaf.runId());assertEquals(fact.sourceId(),leaf.sourceId());assertEquals(fact.businessDate(),leaf.day());assertEquals("article_revision",CanonicalJson.parse(leaf.referenceJson()).get("kind").asText());assertEquals(h.h.done.availableAt(),leaf.availableAt());assertTrue(leaf.effectiveValid());assertFalse(leaf.blocked());assertFalse(leaf.toString().contains(leaf.itemId()));}assertThrows(UnsupportedOperationException.class,leaves::clear);assertSame(captured,h.rr(()->h.service.verifyObserved(captured)));}
    @Test void NativeInvalidationOfAnUnselectedLeafChangesFactsAndInvalidatesOldCapture(){var old=h.capture();var selected=h.h.done.finalResult().result().selected().stream().map(SourceValueFinalResult.Selected::itemId).collect(java.util.stream.Collectors.toSet());var unselected=old.entityLeaves().stream().filter(l->!selected.contains(l.itemId())).findFirst().orElseThrow();h.db().jdbc.update("UPDATE article_revisions SET effective_valid=0,validity_revision=validity_revision+1 WHERE id=?",CanonicalJson.parse(unselected.referenceJson()).get("id").asText());assertThrows(RuntimeException.class,()->h.rr(()->h.service.verifyObserved(old)));var changed=h.capture().entityLeaves().stream().filter(l->l.itemId().equals(unselected.itemId())).findFirst().orElseThrow();assertFalse(changed.effectiveValid());assertEquals(unselected.validityRevision()+1,changed.validityRevision());assertEquals(unselected.bodyJson(),changed.bodyJson());assertEquals(unselected.referenceJson(),changed.referenceJson());}
    @Test void CurrentBlockedStateIsExplicitAndCannotReplaceTheOriginalBody(){var old=h.capture();var leaf=old.entityLeaves().getFirst();h.db().jdbc.update("UPDATE source_run_items SET state='excluded' WHERE id=?",leaf.itemId());assertThrows(RuntimeException.class,()->h.rr(()->h.service.verifyObserved(old)));var fresh=h.capture().entityLeaves().stream().filter(l->l.itemId().equals(leaf.itemId())).findFirst().orElseThrow();assertTrue(fresh.blocked());assertEquals(leaf.bodyJson(),fresh.bodyJson());assertEquals(leaf.bodyHash(),fresh.bodyHash());}
    @Test void MissingAnyImmutableLeafPreservesTheSourceGapWithoutGrantingPartialEntityLeaves(){var id=h.capture().entityLeaves().getFirst().itemId();h.db().jdbc.update("UPDATE source_run_items SET article_revision_id=NULL WHERE id=?",id);var fresh=h.capture();assertTrue(fresh.entityLeaves().isEmpty());assertTrue(fresh.value().missing().stream().anyMatch(m->m.reason().equals("source_leaf_unproven")));assertFalse(fresh.successfulOriginalEmpty());}
    @Test void ARealOriginalZeroPlanHasNoEntityLeavesAndCurrentArticleTablesAreIrrelevant()throws Exception{var original=h.capture();h.db().jdbc.execute("CREATE TABLE articles(id VARCHAR(64),title VARCHAR(512))");h.db().jdbc.update("INSERT INTO articles VALUES('fictional-current','Fictional misleading current body')");assertEquals(original.entityLeaves(),h.capture().entityLeaves());h.RealOriginalZeroPlanRemainsExplicitNativeEmptyWithoutNewsBody();assertTrue(h.capture().entityLeaves().isEmpty());assertTrue(h.capture().successfulOriginalEmpty());}
}
